typedef enum {
LITERAL,
VAR,
FUNC,
} NodeType;
struct Node {
struct Node *left;
struct Node *right;
union {
int literal;
char *var;
char *func;
} data;
NodeType type;
};

typedef struct EnvEntry {
char *key;
Node *val;
struct EnvEntry *next;
} EnvEntry;

struct Node {
struct Node *left;
struct Node *right;
union {
int literal;
char *var;
int index;
char *call;
struct Node *closure;
struct Node *nativeFunc;
} data;
NodeType type;
};

typedef struct Chunk {
Node nodes[CHUNK_SIZE];
struct Chunk *next;
} Chunk;
